print("ann ret: %.2f%% | sharpe(ann): %.2f | maxDD: %.2f%% | calmar: %.2f" % (ann * 100, sharpe, mdd * 100, ann / mdd if mdd > 0 else 0))
print("\nblock details (date, regime, gross%, cost%, net%, equity%):")
for drow in details:
    print(drow)

